package com.sumaye.restaurant.controller; import com.sumaye.restaurant.dto.ReservationRequest; import com.sumaye.restaurant.model.Reservation; import com.sumaye.restaurant.service.ReservationService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.security.core.userdetails.UserDetails; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/branches/{branchId}/reservations") @RequiredArgsConstructor public class ReservationController {private final ReservationService service;@GetMapping @PreAuthorize("hasAnyRole('OWNER','ADMIN','MANAGER','WAITER')") public List<Reservation> list(@PathVariable Long branchId,@RequestParam(required=false)LocalDate date){return service.today(branchId,date==null?LocalDate.now():date);}@PostMapping @PreAuthorize("hasAnyRole('OWNER','ADMIN','MANAGER','WAITER')") public ResponseEntity<Reservation> create(@PathVariable Long branchId,@Valid @RequestBody ReservationRequest r,@AuthenticationPrincipal UserDetails u){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(branchId,r,u.getUsername()));}@PutMapping("/{id}/status/{status}") @PreAuthorize("hasAnyRole('OWNER','ADMIN','MANAGER','WAITER')") public Reservation status(@PathVariable Long branchId,@PathVariable Long id,@PathVariable Reservation.Status status){return service.status(branchId,id,status);}}
